H,W=29,27
G=[[5]*W for _ in range(H)]
# source motif, with its center at (1,2)
seed=[[3,6,1],[9,3,7],[6,5,5]]
for i in range(3):
    for j in range(3):
        G[i][j+1]=seed[i][j]
markers=[(1,6),(1,19),(2,11),(2,15),(3,24),(4,7),(5,3),(6,14),(6,18),(7,25),(8,4),(9,8),(9,15),(9,20),(11,1),(11,24),(12,12),(13,20),(14,4),(14,8),(14,15),(16,11),(16,21),(17,17),(17,25),(19,1),(19,8),(19,13),(22,15),(22,22),(23,6),(23,11),(24,18),(26,1),(26,13),(26,23),(27,9)]
for r,c in markers:G[r][c]=0
# Stamp seed's non-background cells around each marker, aligning the seed center to marker.
for r,c in markers:
    for i in range(3):
        for j in range(3):
            v=seed[i][j]
            rr=r+i-1; cc=c+j-1
            if v!=5 and 0<=rr<H and 0<=cc<W:
                G[rr][cc]=v
assert len(G)==29 and all(len(row)==27 for row in G)
print('markers',len(markers),'rows',len(G),'widths',sorted(set(map(len,G))))
print(__import__('json').dumps(G,separators=(',',':')))
